mapper.select:
select d1.* from ( SELECT pm.matcode, pm.matname, sts.Storesiteno, ii.qty, NVL(ii.collectedqty,0) as collectedqty, ii.batchno, NVL(i.indesc,' ') AS indesc, ii.sn, str.storeroomno AS storeroomno, ibl.subinventory_code, i.forcesite, i.forcebatch, NVL(i.data2,' ') as data2, NVL(i.data3,' ') as data3, i.intaskno, i.taskcomment, NVL(ibl.workstation,'N') AS workstation, ibl.palletno, i.data1, ii.intaskitemid, ii.intaskitemid AS ID, ii.intaskid, ii.materialid, ii.inbillid, str.storeroomname, str.roomtag, e.operation, e.userid, NVL(ii.instate,0) AS instate, NVL(i.collecter,0) AS collecter, NVL(ii.collecter,0) AS i_collecter, NVL(i.collecter,0) AS t_collecter, i.indate, p.parno, NVL(inf.transfertype,'0') transfertype, inf.proofno, inf.protype, inf.orderno FROM intask i, intaskitem ii, pm_material pm, storeroom str, storesite sts, inproof inf, inbill ibl, (select distinct r.USER_ID as userid,m.STOREROOMID as operation from sys_user_role r,sys_role_room m where r.ROLE_ID=m.ROLE_ID) e, partner p WHERE i.intaskid=ii.intaskid AND ii.materialid = pm.pm_materialid AND i.storeroomid = str.storeroomid AND ii.hintedsite = sts.storesiteid(+) AND inf.inproofid = i.tasksource AND ibl.inproofid = inf.inproofid AND inf.partnerid = p.partnerid(+) AND ibl.materialid = pm.pm_materialid AND ibl.inbillid = ii.inbillid AND str.storeroomid = e.operation AND (NVL(ii.qty,0)-NVL(ii.collectedqty,0)) > 0 and nvl(ii.collecter,0) = #{i_collecter} and nvl(ii.instate,0) = #{instate} and nvl(e.userid,0) = #{userId} and nvl(str.roomtag,0)= #{roomtag} and nvl(inf.transfertype,0) = #{transfertype}
and nvl(i.intaskno,0) = #{intaskno} and nvl(i.intaskid,0) = #{intaskid}
)d1 where 1=1
and ( d1.matcode like concat(concat('%',#{searchKey}),'%') or d1.storesiteno like concat(concat('%',#{searchKey}),'%') )
order by d1.indate desc,d1.taskcomment desc, d1.intaskno desc,d1.storesiteno asc,d1.matcode asc
order by d1.${sortColumn} ${sortType}

select distinct d1.proofno, d1.orderno, d1.data3, d1.palletno, d1.storeroomno, d1.intaskno, d1.intaskid from ( SELECT pm.matcode, pm.matname, sts.Storesiteno, ii.qty, NVL(ii.collectedqty,0) as collectedqty, ii.batchno, NVL(i.indesc,' ') AS indesc, ii.sn, str.storeroomno AS storeroomno, ibl.subinventory_code, i.forcesite, i.forcebatch, NVL(i.data2,' ') as data2, NVL(i.data3,' ') as data3, i.intaskno, i.taskcomment, NVL(ibl.workstation,'N') AS workstation, ibl.palletno, i.data1, ii.intaskitemid, ii.intaskitemid AS ID, ii.intaskid, ii.materialid, ii.inbillid, str.storeroomname, str.roomtag, e.operation, e.userid, NVL(ii.instate,0) AS instate, NVL(i.collecter,0) AS collecter, NVL(ii.collecter,0) AS i_collecter, NVL(i.collecter,0) AS t_collecter, i.indate, p.parno, NVL(inf.transfertype,'0') transfertype, inf.proofno, inf.protype, inf.orderno FROM intask i, intaskitem ii, pm_material pm, storeroom str, storesite sts, inproof inf, inbill ibl, (select distinct r.USER_ID as userid,m.STOREROOMID as operation from sys_user_role r,sys_role_room m where r.ROLE_ID=m.ROLE_ID) e, partner p WHERE i.intaskid=ii.intaskid AND ii.materialid = pm.pm_materialid AND i.storeroomid = str.storeroomid AND ii.hintedsite = sts.storesiteid(+) AND inf.inproofid = i.tasksource AND ibl.inproofid = inf.inproofid AND inf.partnerid = p.partnerid(+) AND ibl.materialid = pm.pm_materialid AND ibl.inbillid = ii.inbillid AND str.storeroomid = e.operation AND (NVL(ii.qty,0)-NVL(ii.collectedqty,0)) > 0 and nvl(i.intaskid,0) = #{intaskid} and nvl(ii.collecter,0) = #{i_collecter} and nvl(ii.instate,0) = #{instate} and nvl(e.userid,0) = #{userId} and i.taskcomment like concat(concat('%',#{taskcomment}),'%') and nvl(str.roomtag,0)= #{roomtag} and nvl(ibl.workstation,0) = #{workstation} )d1 where 1=1
order by d1.proofno desc, d1.intaskno desc, d1.palletno asc
order by d1.${sortColumn} ${sortType}

mapper.update:
update intaskitem
intaskid = #{intaskid}, inbillid = #{inbillid}, materialid = #{materialid}, hintedsite = #{hintedsite}, qty = #{qty}, indesc = #{indesc}, dataversion = #{dataversion}, data1 = #{data1}, data2 = #{data2}, data3 = #{data3}, data4 = #{data4}, data5 = #{data5}, data6 = #{data6}, data7 = #{data7}, data8 = #{data8}, inorderid = #{inorderid}, batchno = #{batchno}, sn = #{sn}, collectedqty = #{collectedqty}, collecter = #{collecter}, instate = #{instate}, collect_date = #{collectDate}, transaction_id = #{transactionId}, productline = #{productline}, workstation = #{workstation}, palletno = #{palletno},
where intaskitemid = #{intaskitemid}
